        bomb.state = 'planted';
        bomb.plantedAt = site;
        bomb.fuseLeft = 35;
        bomb.plantProgress = 0;
        p.hasBomb = false;
        game.money += 300;
        game.events.push({ type: 'bombPlanted', site, x: SITES[site].x, z: SITES[site].z });
        audio.beep(true);
      }
    } else {
      bomb.plantProgress = Math.max(0, bomb.plantProgress - dt * 2);
    }
    return;
  }

