/* DUSTLINE — HUD styles. Dusk palette: warm sand, teal, rust, near-black. */
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { width: 100%; height: 100%; overflow: hidden; background: #14161a; }
body { font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif; color: #f5efe4; }
